CREATE COLUMN TABLE "TEST_AP"."OFND" ("AbsEntry" INTEGER CS_INT NOT NULL , "ObjectCode" NVARCHAR(20) NOT NULL , "DocSubtype" NVARCHAR(2) DEFAULT '--' NOT NULL , PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
